import type * as React from "react";

import { Label } from "@/components/ui/label";
import { cn } from "@/lib/utils";

// Minimal shadcn/ui Field primitives, inlined so the block installs self-contained.
function FieldGroup({ className, ...props }: React.ComponentProps<"div">) {
	return (
		<div
			className={cn("group/field-group flex w-full flex-col gap-6", className)}
			data-slot="field-group"
			{...props}
		/>
	);
}

function Field({ className, ...props }: React.ComponentProps<"div">) {
	return (
		<div
			className={cn("group/field flex w-full flex-col gap-2.5", className)}
			data-slot="field"
			role="group"
			{...props}
		/>
	);
}

function FieldLabel({ className, ...props }: React.ComponentProps<typeof Label>) {
	return (
		<Label
			className={cn("w-fit leading-snug", className)}
			data-slot="field-label"
			{...props}
		/>
	);
}

export { Field, FieldGroup, FieldLabel };

import type * as React from "react";
import { cn } from "@/lib/utils";
import { cva, type VariantProps } from "class-variance-authority";

const DecorIconVariants = cva(
	"pointer-events-none absolute z-1 size-5 shrink-0 stroke-1 stroke-muted-foreground",
	{
		variants: {
			position: {
				"top-left":
					"top-0 left-0 -translate-x-[calc(50%+0.5px)] -translate-y-[calc(50%+0.5px)]",
				"top-right":
					"top-0 right-0 translate-x-[calc(50%+0.5px)] -translate-y-[calc(50%+0.5px)]",
				"bottom-right":
					"right-0 bottom-0 translate-x-[calc(50%+0.5px)] translate-y-[calc(50%+0.5px)]",
				"bottom-left":
					"bottom-0 left-0 -translate-x-[calc(50%+0.5px)] translate-y-[calc(50%+0.5px)]",
			},
		},
		defaultVariants: {
			position: "top-left",
		},
	}
);

type DecorIconProps = React.ComponentProps<"svg"> &
	VariantProps<typeof DecorIconVariants>;

export function DecorIcon({ position, className, ...props }: DecorIconProps) {
	return (
		<svg
			aria-hidden="true"
			className={cn(DecorIconVariants({ position, className }))}
			fill="none"
			stroke="currentColor"
			strokeLinecap="round"
			strokeLinejoin="round"
			viewBox="0 0 24 24"
			xmlns="http://www.w3.org/2000/svg"
			{...props}
		>
			<path d="M5 12h14" />
			<path d="M12 5v14" />
		</svg>
	);
}
